"""Re-evaluate only pilot caches whose fit JSON was regenerated by full fitting."""
import json,time
from concurrent.futures import ProcessPoolExecutor
from common import W,tasks,key,sha,dump
from evaluate import initialize,one


def main():
    started=time.monotonic();assert json.loads((W/'FITS_COMPLETE.json').read_text())['status']=='COMPLETE'
    tags={r['tag'] for r in json.loads((W/'SOLVER_PREFLIGHT.json').read_text())['records']}
    stale=[];before=[]
    for t in tasks():
        if key(t) not in tags:continue
        p=W/'evaluation'/(key(t)+'.json');r=json.loads(p.read_text())
        if r['fit_sha256']!=sha(W/'fits'/p.name):
            stale.append(t);before.append(dict(tag=key(t),old_evaluation_sha256=sha(p),old_fit_sha256=r['fit_sha256']))
    archive=W/'pilot_evaluation';archive.mkdir(exist_ok=True)
    for t in stale:
        for suffix in ['.json','.npz']:
            p=W/'evaluation'/(key(t)+suffix)
            if p.exists():__import__('shutil').copy2(p,archive/p.name)
    with ProcessPoolExecutor(max_workers=8,initializer=initialize) as pool:results=list(pool.map(one,stale))
    dump(W/'REFRESH_PILOT_EVALUATION.json',dict(status='PASS',reason='Pilot fits were regenerated with different timing metadata. Recompute their metrics against final fit hashes with the unchanged evaluator; retain old pilot files separately. No solver, point, metric or threshold changed.',
        frames=len(results),before=before,records=results,seconds=time.monotonic()-started))


if __name__=='__main__':main()
